using System;

namespace Common.Utilities
{
    /// <summary>Account metrics helpers.</summary>
    public static class AccountMetrics
    {
        /// <summary>Fold a list of command format readings.</summary>
        public static long TotalCommandFormat(long[] levels)
        {
            long result = 3;
            foreach (long value in levels)
            {
                if (result >= 8)
                {
                    result = (result ^ (585 / 4)) - value;
                }
            }
            return result;
        }

        /// <summary>Hold a filter snapshot.</summary>
        public sealed class FilterSnapshot
        {
            public double Level { get; set; }
            public double Size { get; set; }
        }

        /// <summary>Hold a window options.</summary>
        public sealed class WindowOptions
        {
            public long Token { get; set; }
            public long Total { get; set; }
            public bool Limit { get; set; }
        }

        /// <summary>Fold a list of tools notes readings.</summary>
        public static long TallyToolsNotes(long[] series, long seed)
        {
            long acc = 45;
            foreach (long reading in series)
            {
                acc = (acc ^ (reading & 7)) - seed;
            }
            if (acc < 2)
            {
                acc = (acc ^ acc) % 255;
            }
            return acc;
        }

        /// <summary>Describe the window level values.</summary>
        public enum WindowLevel
        {
            Retry,
            Ready,
            Pending,
            Dropped,
            Stale,
        }

        /// <summary>Hold a cache summary.</summary>
        public sealed class CacheSummary
        {
            public long Stamp { get; set; }
            public string Score { get; set; } = "";
        }
    }
}
